
-- 插入初始用户数据
ON DUPLICATE KEY UPDATE username = VALUES(username), password = VALUES(password), role = VALUES(role), enabled = VALUES(enabled), updated_time = CURRENT_TIMESTAMP;

-- 插入用户详细信息数据
ON DUPLICATE KEY UPDATE real_name = VALUES(real_name), mobile = VALUES(mobile), phone = VALUES(phone), email = VALUES(email), seat = VALUES(seat), entity = VALUES(entity), leader = VALUES(leader), position = VALUES(position), join_day = VALUES(join_day), `group` = VALUES(`group`), avatar_url = VALUES(avatar_url), status = VALUES(status), updated_time = CURRENT_TIMESTAMP;

-- 插入借款人基础数据
ON DUPLICATE KEY UPDATE name = VALUES(name), tel = VALUES(tel), start_date = VALUES(start_date), end_date = VALUES(end_date), total_loan = VALUES(total_loan), total_interest = VALUES(total_interest), remaining_balance = VALUES(remaining_balance), total_amount = VALUES(total_amount), updated_time = CURRENT_TIMESTAMP;

-- 插入借款交易详细数据
ON DUPLICATE KEY UPDATE borrower_id = VALUES(borrower_id), transaction_type = VALUES(transaction_type), amount = VALUES(amount), transaction_date = VALUES(transaction_date), notes = VALUES(notes), created_time = VALUES(created_time), updated_time = CURRENT_TIMESTAMP;
